files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --border: #2a2a4a;
  --focus: #f5c542;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-bottom: 20px;
}

.course-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.form-row {
  display: flex;
  gap: 12px;
}

.form-row .form-group {
  flex: 1;
}

label {
  font-size: 0.9rem;
  color: var(--text-muted);
}

input, select {
  font: inherit;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  width: 100%;
}

input:focus, select:focus {
  outline: 2px solid var(--focus);
  outline-offset: 1px;
  border-color: var(--focus);
}

.btn-primary {
  font: inherit;
  font-weight: 600;
  padding: 12px;
  border: none;
  border-radius: 8px;
  background: var(--primary);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

.btn-primary:hover {
  background: var(--primary-hover);
}

.btn-primary:active {
  transform: scale(0.98);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.course-list-section h2 {
  font-size: 1.1rem;
  margin-bottom: 8px;
}

.course-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.course-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: var(--bg);
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.course-info {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  font-size: 0.95rem;
}

.course-name {
  font-weight: 600;
}

.course-meta {
  color: var(--text-muted);
}

.btn-delete {
  font: inherit;
  font-size: 0.85rem;
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.btn-delete:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.btn-delete:active {
  transform: scale(0.96);
}

.btn-delete:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.empty-message {
  color: var(--text-muted);
  font-style: italic;
  font-size: 0.95rem;
  padding: 8px 0;
}

.gpa-display {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

.gpa-label {
  font-size: 1rem;
  color: var(--text-muted);
}

.gpa-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary);
}

@media (max-width: 400px) {
  .form-row {
    flex-direction: column;
  }
  .card {
    padding: 16px;
  }
  .gpa-value {
    font-size: 1.6rem;
  }
}

(function () {
  'use strict';

  const GRADE_POINTS = { A: 4.0, B: 3.0, C: 2.0, D: 1.0, F: 0.0 };

  const form = document.getElementById('course-form');
  const nameInput = document.getElementById('course-name');
  const creditsInput = document.getElementById('credit-hours');
  const gradeSelect = document.getElementById('letter-grade');
  const list = document.getElementById('course-list');
  const emptyMsg = document.getElementById('empty-message');
  const gpaValue = document.getElementById('gpa-value');

  let courses = [];

  function calculateGPA() {
    if (courses.length === 0) return 0;
    let totalCredits = 0;
    let totalPoints = 0;
    for (const c of courses) {
      totalCredits += c.credits;
      totalPoints += GRADE_POINTS[c.grade] * c.credits;
    }
    return totalCredits === 0 ? 0 : totalPoints / totalCredits;
  }

  function render() {
    list.innerHTML = '';
    if (courses.length === 0) {
      emptyMsg.style.display = 'block';
    } else {
      emptyMsg.style.display = 'none';
      for (let i = 0; i < courses.length; i++) {
        const c = courses[i];
        const li = document.createElement('li');
        li.className = 'course-item';

        const info = document.createElement('div');
        info.className = 'course-info';

        const nameSpan = document.createElement('span');
        nameSpan.className = 'course-name';
        nameSpan.textContent = c.name;

        const metaSpan = document.createElement('span');
        metaSpan.className = 'course-meta';
        metaSpan.textContent = c.credits + ' cr \u00b7 ' + c.grade;

        info.appendChild(nameSpan);
        info.appendChild(metaSpan);

        const delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.className = 'btn-delete';
        delBtn.textContent = 'Remove';
        delBtn.setAttribute('aria-label', 'Remove ' + c.name);
        delBtn.addEventListener('click', function () {
          courses.splice(i, 1);
          render();
        });

        li.appendChild(info);
        li.appendChild(delBtn);
        list.appendChild(li);
      }
    }
    gpaValue.textContent = calculateGPA().toFixed(2);
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    const name = nameInput.value.trim();
    const credits = parseFloat(creditsInput.value);
    const grade = gradeSelect.value;

    if (!name) {
      nameInput.focus();
      return;
    }
    if (isNaN(credits) || credits <= 0) {
      creditsInput.focus();
      return;
    }
    if (!GRADE_POINTS.hasOwnProperty(grade)) {
      gradeSelect.focus();
      return;
    }

    courses.push({ name: name, credits: credits, grade: grade });
    form.reset();
    creditsInput.value = '3';
    nameInput.focus();
    render();
  });

  render();
})();
